import{c as l,Z as o,Q as r,j as n,m as s,o as e}from"./chunks/framework.DOi4mjdC.js";const f=JSON.parse('{"title":"声声慢·寻寻觅觅","description":"","frontmatter":{"title":"声声慢·寻寻觅觅","author":"李清照","dynasty":"宋"},"headers":[],"relativePath":"books/shici/songci/3.md","filePath":"books/shici/songci/3.md"}'),h={name:"books/shici/songci/3.md"};function c(p,a,u,d,_,m){const t=o("PoemAuthor"),i=o("PoemNav");return r(),n("div",null,[a[0]||(a[0]=s('<h1 id="声声慢·寻寻觅觅" tabindex="-1">声声慢·寻寻觅觅 <a class="header-anchor" href="#声声慢·寻寻觅觅" aria-label="Permalink to &quot;声声慢·寻寻觅觅&quot;">​</a></h1><p><strong>[宋] <a href="/authors/liqingzhao.html">李清照</a></strong></p><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><p>寻寻觅觅，冷冷清清，凄凄惨惨戚戚。乍暖还寒时候，最难将息。三杯两盏淡酒，怎敌他、晚来风急？雁过也，正伤心，却是旧时相识。</p><p>满地黄花堆积，憔悴损，如今有谁堪摘？守着窗儿，独自怎生得黑？梧桐更兼细雨，到黄昏、点点滴滴。这次第，怎一个愁字了得！</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ul><li>将息：调养休息</li><li>淡酒：薄酒</li><li>敌：抵挡</li><li>旧时相识：指从前见过的雁，暗指故乡和往事</li><li>黄花：菊花</li><li>憔悴损：枯萎凋零</li><li>堪摘：值得采摘</li><li>怎生：怎么</li><li>次第：情形、光景</li></ul><h2 id="译文" tabindex="-1">译文 <a class="header-anchor" href="#译文" aria-label="Permalink to &quot;译文&quot;">​</a></h2><p>我到处寻找，却只找到冷冷清清，内心充满凄惨悲戚。在这忽暖忽寒的时节，最难以调养休息。喝上三两杯淡酒，怎么能抵挡得住傍晚急来的寒风？大雁飞过，我正伤心，却发现它们正是从前相识的旧雁。</p><p>满地堆积着枯萎的菊花，已经憔悴凋零，如今还有谁值得我去采摘？独自守着窗户，怎么才能挨到天黑？梧桐叶上又落下细雨，一直到黄昏时分，雨声点点滴滴。这样的情形，怎是一个&quot;愁&quot;字能够概括得了的！</p><h2 id="赏析" tabindex="-1">赏析 <a class="header-anchor" href="#赏析" aria-label="Permalink to &quot;赏析&quot;">​</a></h2><p>这首词是李清照晚年所作，是婉约词的代表作。当时词人经历了国破、家亡、夫死的巨变，孤苦伶仃，处境凄凉。词中通过描写残秋的景色和孤寂的生活，抒发了深沉的哀愁。</p><p>开篇连用七组叠字&quot;寻寻觅觅，冷冷清清，凄凄惨惨戚戚&quot;，前所未有，将词人空虚、寂寞、悲伤的心境层层推进，堪称千古绝唱。&quot;乍暖还寒&quot;既写天气，也暗示词人内心的起伏不定。</p><p>上片写词人借酒浇愁，却敌不过晚风；见雁伤心，因为那是旧时相识，勾起对往昔的追忆。下片写满地残菊，无人共摘；独守窗前，度日如年；梧桐细雨，点点滴滴，更添愁绪。</p><p>结尾&quot;这次第，怎一个愁字了得&quot;，将全词的愁情推向高潮，言有尽而意无穷。全词语言朴素自然，情感真挚深沉，将个人之愁与家国之痛融为一体，感人至深。</p>',15)),e(t,{name:"李清照",years:"1084年－约1155年",desc:"号易安居士，宋代著名女词人，婉约词派代表，有“千古第一才女”之称。其词前期多写悠闲生活，后期多悲叹身世。",link:"/authors/liqingzhao"}),e(i)])}const b=l(h,[["render",c]]);export{f as __pageData,b as default};
